L000035	  \title{Ellipticity-Controlled Bright-Dark Coherence Transition in Monolayer WSe$_2$}
L000036	
L000037	\author{Kang Lan}
L000038	\affiliation{School of Physics and Physical Engineering, Qufu Normal University, 273165, Qufu, China}
